import React, { useState, useCallback } from 'react';
import SystemBar from '../components/Plc/SystemBar';
import MotorGrid from '../components/Plc/MotorGrid';
import MotorDialog from '../components/Plc/MotorDialog';
import PhotoGrid from '../components/Plc/PhotoGrid';
import PhotoDialog from '../components/Plc/PhotoDialog';
import FaultPanel from '../components/Plc/FaultPanel';
import RawRegisters from '../components/Plc/RawRegisters';
import RegisterMap from '../components/Plc/RegisterMap';
import ModbusLogTable from '../components/Modbus/ModbusLogTable';
import { usePlc } from '../hooks';
import { singlePointApi } from '../api';

export default function SinglePointPage({ toast }) {
  const { status, refresh } = usePlc();
  const [motorDialog, setMotorDialog] = useState(null);
  const [photoDialog, setPhotoDialog] = useState(null);

  const handleToggleSystem = useCallback(async (field) => {
    if (!status?.system) return;
    try {
      const res = await singlePointApi.setSystem(field, !status.system[field]);
      toast(res.message, res.success ? 'success' : 'error');
      if (res.success) refresh();
    } catch { toast('请求失败', 'error'); }
  }, [status, toast, refresh]);

  const handleResetAll = useCallback(async () => {
    if (!window.confirm('确定要复位所有状态吗？\n\n这将停止所有电机、清除所有光电信号和故障，恢复系统就绪状态。')) return;
    try {
      const res = await singlePointApi.resetAll();
      toast(res.message, res.success ? 'success' : 'error');
      if (res.success) refresh();
    } catch { toast('请求失败', 'error'); }
  }, [toast, refresh]);

  const hasEmergency = status?.system?.emergencyStop;
  const isRunning = status?.system?.running;
  const hasFault = !!status?.system?.fault;
  const pageStateClass = hasEmergency ? 'sp-state-emergency' : hasFault ? 'sp-state-fault' : isRunning ? 'sp-state-running' : 'sp-state-idle';

  return (
    <div className={`sp-container ${pageStateClass}`}>
      <div className="sp-system-bar">
        <div className="sys-item">
          <span className="sys-icon">⚡</span><span className="sys-label">系统运行</span>
          <span className={`sys-indicator ${isRunning ? 'on' : 'off'}`}>{isRunning ? 'ON' : 'OFF'}</span>
        </div>
        <div className="sys-item">
          <span className="sys-icon">⚠️</span><span className="sys-label">系统故障</span>
          <span className={`sys-indicator ${status?.system?.fault ? 'warn' : 'off'}`}>{status?.system?.fault ? '故障' : '正常'}</span>
        </div>
        <div className="sys-item clickable" onClick={() => handleToggleSystem('emergencyStop')}>
          <span className="sys-icon">🛑</span><span className="sys-label">急停</span>
          <span className={`sys-indicator ${hasEmergency ? 'warn' : 'off'}`}>{hasEmergency ? '急停!' : '正常'}</span>
        </div>
        <div className="sys-item clickable" onClick={() => handleToggleSystem('remoteMode')}>
          <span className="sys-icon">📡</span><span className="sys-label">远程模式</span>
          <span className={`sys-indicator ${status?.system?.remoteMode ? 'on' : 'off'}`}>{status?.system?.remoteMode ? 'ON' : 'OFF'}</span>
        </div>
        <div className="sys-spacer" />
        <button className="btn btn-danger" onClick={handleResetAll} style={{ fontSize: 11 }}>🔄 一键复位</button>
        <button className="btn btn-outline" onClick={refresh} style={{ fontSize: 11 }}>🔄 刷新</button>
      </div>

      <div className="sp-main-row">
        <div className="sp-panel sp-motors">
          <div className="sp-panel-header">
            <h2>🔧 电机运行状态 (HR5)</h2>
            <span className="sp-subtitle">点击卡片切换启停 · 右键设置故障</span>
          </div>
          <MotorGrid motors={status?.motors} onMotorClick={setMotorDialog} />
        </div>
        <div className="sp-panel sp-photos">
          <div className="sp-panel-header">
            <h2>💡 光电传感器 (HR6-HR7)</h2>
            <span className="sp-subtitle">点击光电设置遮挡时长</span>
          </div>
          <PhotoGrid photos={status?.photos} onPhotoClick={setPhotoDialog} />
        </div>
      </div>

      <div className="sp-bottom-row">
        <div className="sp-panel sp-faults">
          <div className="sp-panel-header">
            <h2>🔴 故障位 (HR7 低字节)</h2>
            <span className="sp-subtitle">非电机独立故障</span>
          </div>
          <FaultPanel faults={status?.faults} motors={status?.motors} toast={toast} onUpdated={refresh} />
        </div>
        <div className="sp-panel sp-raw">
          <div className="sp-panel-header">
            <h2>📋 寄存器原始值</h2>
            <span className="sp-subtitle">实时 Hex 快照</span>
          </div>
          <RawRegisters rawRegs={status?.rawRegisters} />
        </div>
      </div>

      <RegisterMap />
      <ModbusLogTable />

      <MotorDialog motor={motorDialog} onClose={() => setMotorDialog(null)} toast={toast} onUpdated={refresh} />
      <PhotoDialog photo={photoDialog} onClose={() => setPhotoDialog(null)} toast={toast} onUpdated={refresh} />
    </div>
  );
}
